/**
 * Same-origin workspace downloads (`/files/download?path=...`) generated by the agent must
 * download directly: no new tab, no SPA navigation, no preview. Returns true when handled.
 */
export function workspaceDownloadTarget(href: string, origin: string): { url: string; name: string } | undefined {
  if (!href) return
  let url: URL
  try {
    url = new URL(href, origin)
  } catch {
    return
  }
  if (url.origin !== origin || url.pathname !== "/files/download") return
  const path = url.searchParams.get("path")
  if (!path) return
  const name = path.split("/").filter(Boolean).pop()
  if (!name) return
  return { url: url.pathname + url.search, name }
}

export function markWorkspaceDownload(node: HTMLAnchorElement, origin = globalThis.location?.origin ?? "") {
  if (!origin) return false
  const target = workspaceDownloadTarget(node.getAttribute("href") ?? "", origin)
  if (!target) return false
  node.setAttribute("href", target.url)
  node.setAttribute("download", target.name)
  node.removeAttribute("target")
  node.setAttribute("rel", "noopener noreferrer")
  node.setAttribute("data-workspace-download", "")
  node.classList.add("workspace-download-link")
  return true
}
